param([ValidateSet('production','development')]$Mode='production')
$ErrorActionPreference='Stop';$Root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$Run=Join-Path $Root 'data\run';New-Item -ItemType Directory -Force -Path $Run|Out-Null
$EnvFile=Join-Path $Root '.env.local';if(-not (Test-Path $EnvFile)){throw 'Execute Install-ShopLive.ps1 primeiro'}
Get-Content -LiteralPath $EnvFile|ForEach-Object{if($_ -match '^([^#=]+)=(.*)$'){[Environment]::SetEnvironmentVariable($Matches[1],$Matches[2],'Process')}}
$Agent=Join-Path $Root 'apps\local-agent';$Python=Join-Path $Agent '.venv\Scripts\python.exe';$AgentProcess=Start-Process -FilePath $Python -ArgumentList @('-m','uvicorn','app.main:app','--app-dir',$Agent,'--host','127.0.0.1','--port','8765') -PassThru -WindowStyle Hidden;$AgentProcess.Id|Set-Content -LiteralPath (Join-Path $Run 'agent.pid')
$Dashboard=(Resolve-Path (Join-Path $Root '..\dashboard')).Path;if($Mode -eq 'development'){$Ui=Start-Process -FilePath 'npm.cmd' -ArgumentList @('run','dev','--','--host','127.0.0.1','--port','3017') -WorkingDirectory $Dashboard -PassThru -WindowStyle Hidden}else{$Ui=Start-Process -FilePath $Python -ArgumentList @((Join-Path $Root 'scripts\Serve-ShopLive.py'),'--port','3017','--directory',(Join-Path $Dashboard 'dist')) -PassThru -WindowStyle Hidden};$Ui.Id|Set-Content -LiteralPath (Join-Path $Run 'dashboard.pid')
Write-Host "Shop LIVE iniciado em modo ${Mode}: http://127.0.0.1:3017/shop-live"
